#include <iostream>
#include <cmath>
#include <iomanip>

int main() {
    // Test case: quad nodes (0,0), (2,0), (2,1.5), (0,1.5)
    double nodes[4][2] = {{0.0, 0.0}, {2.0, 0.0}, {2.0, 1.5}, {0.0, 1.5}};
    const double E  = 200e9;   // Pa
    const double nu = 0.3;
    const double t  = 0.01;    // m

    // NASTRAN KQDMEM triangle decomposition (1-based node indices)
    // Triangle I  : 1,2,4
    // Triangle II : 2,3,1
    // Triangle III: 3,4,2
    // Triangle IV : 4,1,3
    const int M[12] = {1, 2, 4, 2, 3, 1, 3, 4, 2, 4, 1, 3};

    double K[8][8];
    for (int i = 0; i < 8; ++i)
        for (int j = 0; j < 8; ++j)
            K[i][j] = 0.0;

    // Plane-stress material matrix D
    const double f = E / (1.0 - nu * nu);
    const double D[3][3] = {
        {f,        f * nu,   0.0},
        {f * nu,   f,        0.0},
        {0.0,      0.0,      f * (1.0 - nu) / 2.0}
    };

    for (int tri = 0; tri < 4; ++tri) {
        const int n0 = M[3 * tri + 0] - 1;
        const int n1 = M[3 * tri + 1] - 1;
        const int n2 = M[3 * tri + 2] - 1;

        const double x1 = nodes[n0][0], y1 = nodes[n0][1];
        const double x2 = nodes[n1][0], y2 = nodes[n1][1];
        const double x3 = nodes[n2][0], y3 = nodes[n2][1];

        // Signed area (twice)
        const double A = 0.5 * ((x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1));

        // Strain-displacement matrix B (3x6)
        const double b1 = y2 - y3, b2 = y3 - y1, b3 = y1 - y2;
        const double c1 = x3 - x2, c2 = x1 - x3, c3 = x2 - x1;
        double B[3][6] = {
            {b1, 0.0, b2, 0.0, b3, 0.0},
            {0.0, c1, 0.0, c2, 0.0, c3},
            {c1, b1, c2, b2, c3, b3}
        };
        const double inv2A = 1.0 / (2.0 * A);
        for (int i = 0; i < 3; ++i)
            for (int k = 0; k < 6; ++k)
                B[i][k] *= inv2A;

        // DB = D * B
        double DB[3][6];
        for (int i = 0; i < 3; ++i)
            for (int k = 0; k < 6; ++k) {
                DB[i][k] = 0.0;
                for (int m = 0; m < 3; ++m)
                    DB[i][k] += D[i][m] * B[m][k];
            }

        // kt = B^T * DB
        double kt[6][6];
        for (int i = 0; i < 6; ++i)
            for (int k = 0; k < 6; ++k) {
                kt[i][k] = 0.0;
                for (int m = 0; m < 3; ++m)
                    kt[i][k] += B[m][i] * DB[m][k];
            }

        // NASTRAN convention: each sub-triangle uses half the element thickness
        const double scale = (t / 2.0) * std::fabs(A);
        for (int i = 0; i < 6; ++i)
            for (int k = 0; k < 6; ++k)
                kt[i][k] *= scale;

        // Assemble into the 8x8 element stiffness (2 DOF per node)
        const int idx[3] = {n0, n1, n2};
        for (int a = 0; a < 3; ++a)
            for (int b = 0; b < 3; ++b)
                for (int i = 0; i < 2; ++i)
                    for (int jj = 0; jj < 2; ++jj)
                        K[2 * idx[a] + i][2 * idx[b] + jj] += kt[2 * a + i][2 * b + jj];
    }

    // Emit JSON
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 8; ++i) {
        std::cout << "[";
        for (int j = 0; j < 8; ++j) {
            std::cout << std::scientific << std::setprecision(6) << K[i][j];
            if (j < 7) std::cout << ",";
        }
        std::cout << "]";
        if (i < 7) std::cout << ",";
    }
    std::cout << "]}" << std::endl;
    return 0;
}
